using System;
using System.Net;
using System.Net.Http;
using System.Net.Http.Headers;
using System.Net.Sockets;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using CommandCodeManager;
using ModernHost;
public static class ProxyQuotaChecks {
private static void Check(bool value,string message){if(!value)throw new Exception(message);}
private sealed class Handler:HttpMessageHandler {
public string Key;
protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken token){if(request.Method==HttpMethod.Post)Key=request.Headers.Authorization.Parameter;return Task.FromResult(new HttpResponseMessage(HttpStatusCode.OK){Content=new StringContent(request.Method==HttpMethod.Get?"{\"data\":[{\"id\":\"fixture\"}]}":"{\"usage\":{\"input_tokens\":2,\"output_tokens\":1}}",Encoding.UTF8,"application/json")});}
}
public static void Run(){RunAsync().GetAwaiter().GetResult();}
private static async Task RunAsync(){DateTimeOffset now=DateTimeOffset.UtcNow;var data=new AccountData{FetchedAt=now.ToString("o"),Limited=true,Remaining=10,FiveHour=new WindowUsage{Used=100,Cap=100,ResetAt=now.AddHours(2).ToUnixTimeSeconds().ToString()},Weekly=new WindowUsage{Used=100,Cap=100,ResetAt=now.AddDays(2).ToString("o")}};var blocked=new ProxyAccount{Id="blocked",Name="blocked",Key="blocked-key"};LocalProxy.ApplyQuota(blocked,data,now);Check(blocked.BlockedUntil>now&&blocked.Headroom==0,"fresh exhausted windows not excluded");var expired=new ProxyAccount();data.FiveHour.ResetAt=now.AddSeconds(-1).ToString("o");data.Weekly.ResetAt=now.AddSeconds(-1).ToString("o");LocalProxy.ApplyQuota(expired,data,now);Check(expired.BlockedUntil==null,"reset window remained blocked");data.FiveHour.ResetAt=now.AddHours(2).ToString("o");data.FetchedAt=now.AddMinutes(-11).ToString("o");var stale=new ProxyAccount();LocalProxy.ApplyQuota(stale,data,now);Check(stale.BlockedUntil==null,"stale cache locked account");data.FetchedAt=now.ToString("o");data.FiveHour.Used=0;data.MonthlyUsed=100;data.MonthlyTotal=100;data.MonthlyResetAt=now.AddDays(3).ToString("o");var paid=new ProxyAccount{Provider="commandcode"};LocalProxy.ApplyQuota(paid,data,now);Check(paid.BlockedUntil==null,"purchased or free credits ignored");var zeroData=new AccountData{FetchedAt=now.ToString("o"),Remaining=0,MonthlyUsed=100,MonthlyTotal=100,MonthlyResetAt=now.AddDays(1).ToString("o")};var zero=new ProxyAccount();LocalProxy.ApplyQuota(zero,zeroData,now);Check(zero.BlockedUntil>now,"known zero balance not skipped");zeroData.MonthlyResetAt=now.AddSeconds(-1).ToString("o");var renewed=new ProxyAccount();LocalProxy.ApplyQuota(renewed,zeroData,now);Check(renewed.BlockedUntil==null,"old zero balance blocked account after monthly reset");var go=new ProxyAccount{Provider="opencode-go"};LocalProxy.ApplyQuota(go,data,now);Check(go.BlockedUntil>now,"Go monthly exhaustion ignored");var probe=new TcpListener(IPAddress.Loopback,0);probe.Start();int port=((IPEndPoint)probe.LocalEndpoint).Port;probe.Stop();var handler=new Handler();var available=new ProxyAccount{Id="available",Name="available",Key="available-key",Headroom=80};string local=LocalProxy.GenerateKey();using(var gateway=new LocalProxy(()=>new[]{blocked,available},handler))using(var client=new HttpClient(new HttpClientHandler{UseProxy=false})){gateway.Configure(port,local,new[]{"blocked","available"},true);client.DefaultRequestHeaders.Authorization=new AuthenticationHeaderValue("Bearer",local);var response=await client.PostAsync("http://127.0.0.1:"+port+"/v1/chat/completions",new StringContent("{\"model\":\"fixture\"}",Encoding.UTF8,"application/json"));Check(response.IsSuccessStatusCode&&handler.Key=="available-key","exhausted account reached upstream instead of proactive rerouting");gateway.ClearCooldown();response=await client.PostAsync("http://127.0.0.1:"+port+"/v1/chat/completions",new StringContent("{\"model\":\"fixture\"}",Encoding.UTF8,"application/json"));Check(response.IsSuccessStatusCode&&handler.Key=="available-key","clearing runtime pause bypassed exhausted quota");}Console.WriteLine("PASS proactive quota routing, reset timestamps, stale caches, monthly Go limits and additional Command Code credits");}
}
